/**
 * Mock Dataset — deterministic OHLCV data for MOCK.A and MOCK.B.
 *
 * Generated by a fixed seed PRNG. No runtime randomness.
 * Each instrument has exactly 80 trading days ending 2025-12-31.
 * All dates are weekdays (no weekends/holidays) to simulate trading calendar.
 *
 * Invariant: all data passes the checks in invariants.ts.
 */

export interface RawStockRecord {
  date: string;    // YYYY-MM-DD
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

// --- Deterministic PRNG (mulberry32) ---
function mulberry32(seed: number): () => number {
  let t = seed;
  return () => {
    t = (t + 0x6d2b79f5) | 0;
    let x = Math.imul(t ^ (t >>> 15), 1 | t);
    x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}

/** Generate trading days ending on endDate, going back N trading days. */
function generateTradingDays(count: number, endDate: string): string[] {
  const days: string[] = [];
  const end = new Date(endDate + 'T00:00:00Z');
  let d = new Date(end);
  while (days.length < count) {
    const dow = d.getUTCDay(); // 0=Sun, 6=Sat
    if (dow !== 0 && dow !== 6) {
      days.unshift(d.toISOString().slice(0, 10));
    }
    d.setUTCDate(d.getUTCDate() - 1);
  }
  return days;
}

function generateOHLCV(
  dates: string[],
  startPrice: number,
  seed: number,
  avgVolume: number,
): RawStockRecord[] {
  const rng = mulberry32(seed);
  const records: RawStockRecord[] = [];
  let prevClose = startPrice;

  for (const date of dates) {
    // Generate daily change: small drift + volatility
    const drift = (rng() - 0.48) * 0.04; // slight upward bias
    const close = Math.round((prevClose * (1 + drift)) * 100) / 100;
    const intraRange = prevClose * (0.01 + rng() * 0.03);
    const open = Math.round((close + (rng() - 0.5) * intraRange) * 100) / 100;
    const high = Math.round((Math.max(open, close) + rng() * intraRange * 0.5) * 100) / 100;
    const low = Math.round((Math.min(open, close) - rng() * intraRange * 0.5) * 100) / 100;
    const volume = Math.round(avgVolume * (0.5 + rng()));

    records.push({
      date,
      open: Math.max(open, 0.01),
      high: Math.max(high, Math.max(open, close)),
      low: Math.min(low, Math.min(open, close)),
      close: Math.max(close, 0.01),
      volume: Math.max(volume, 0),
    });

    prevClose = Math.max(close, 0.01);
  }

  // Post-process: ensure invariants hold
  for (const r of records) {
    r.high = Math.max(r.high, r.open, r.close);
    r.low = Math.min(r.low, r.open, r.close);
    r.low = Math.max(r.low, 0.01);
  }

  return records;
}

const END_DATE = '2025-12-31';
const TRADING_DAYS = generateTradingDays(80, END_DATE);

export const MOCK_A_DATA: readonly RawStockRecord[] = generateOHLCV(
  TRADING_DAYS,
  25.0,   // start price
  42,     // seed
  500000, // avg volume
);

export const MOCK_B_DATA: readonly RawStockRecord[] = generateOHLCV(
  TRADING_DAYS,
  18.0,   // start price
  137,    // seed
  800000, // avg volume
);

/** Map symbol → data array. */
export function getDataset(symbol: string): readonly RawStockRecord[] | undefined {
  switch (symbol) {
    case 'MOCK.A':
      return MOCK_A_DATA;
    case 'MOCK.B':
      return MOCK_B_DATA;
    default:
      return undefined;
  }
}

/** Get the last trading date in the dataset. */
export function getLastTradingDate(): string {
  return TRADING_DAYS[TRADING_DAYS.length - 1];
}
